import { Link } from "react-router-dom"
import './_pageNotFound.scss';

const PageNotFound  = () => {
  return (
    <div className="not-found">
      <h2>Sorry</h2>
      <p>That page cannot be found</p>
      <Link to="/">Back to the homepage...</Link>
    </div>
  );
}
 
export default PageNotFound;
